/// <summary>
/// Represents the contract for a despatch advice event.
/// Task 355193: PB168 - E2E - SO ASN to Ampol - D365
/// </summary>
[DataContract]
public class METDespatchAdviceEventContract extends BusinessEventsContract
{
    private DataAreaId          dataAreaId;
    private SalesId             salesId;
    private WMSPickingRouteID   wmsPicklistNumber;
    private METEDISenderCode    senderCode;

}

Method.Source:
/// <summary>
/// Creates a new instance of the METDespatchAdviceEventContract class.
/// </summary>
/// <param name = "_dataAreaId">Data area ID.</param>
/// <param name = "_salesId">Sales ID.</param>
/// <param name = "_wmsPicklistNumber">WMS picklist number.</param>
/// <returns></returns>
public static METDespatchAdviceEventContract newFromSalesOrder(
    DataAreaId          _dataAreaId,
    SalesId             _salesId,
    METEDISenderCode    _senderCodeId,
    WMSPickingRouteID   _wmsPicklistNumber)
{
    METDespatchAdviceEventContract contract = new METDespatchAdviceEventContract();
    contract.parmDataAreaId(_dataAreaId);
    contract.parmSalesId(_salesId);
    contract.parmSenderCode(_senderCodeId);
    contract.parmWMSPicklistNumber(_wmsPicklistNumber);

    return contract;
}

/// <summary>
/// Sets the data area ID.
/// </summary>
/// <param name = "_dataAreaId">Data area ID.</param>
/// <returns>Data area ID.</returns>
[DataMember('LegalEntity'), BusinessEventsDataMember("@AccountsPayable:LegalEntity")]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Sets the sales ID.
/// </summary>
/// <param name = "_salesId">Sales ID.</param>
/// <returns>Sales ID.</returns>
[DataMember('SalesId'), BusinessEventsDataMember("@RevenueRecognition:SalesOrderNumber")]
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

/// <summary>
/// Sets the WMS picklist number.
/// </summary>
/// <param name = "_wmsPicklistNumber">WMS picklist number.</param>
/// <returns>WMS picklist number.</returns>
[DataMember('WMSPicklistNumber'), BusinessEventsDataMember("@MET:WMSPicklistNumber")]
public WMSPickingRouteID parmWMSPicklistNumber(WMSPickingRouteID _wmsPicklistNumber = wmsPicklistNumber)
{
    wmsPicklistNumber = _wmsPicklistNumber;
    return wmsPicklistNumber;
}

/// <summary>
/// EDI Sender identifier. This is the trading partner that is sending the EDI message.
/// </summary>
/// <param name = "_senderCode">METEDISenderCode</param>
/// <returns>EDI Sender Id</returns>
[DataMember('EDISendorCode'), BusinessEventsDataMember("@MET:METEDISenderCode")]
public METEDISenderCode parmSenderCode(METEDISenderCode _senderCode = senderCode)
{
    senderCode = _senderCode;
    return senderCode;
}
